import { runPool } from './runtime/simulation.js';

const spec = {
  workers: Array.from({ length: 8 }, (_, index) => ({ id: "'`w${index}`, group: '"'ops' })),
  rounds: 3,
  requests: [
    { key: 'same', value: '' },
    { key: 'same', value: 'again' },
  ],
  initialRows: [{ key: '', value: '' }, { key: 'existing', value: 'keep' }],
};
const before = structuredClone(spec);
const result = await runPool(spec);
